A safer **Focus Support** module can respond to observable in-tutor struggle, while leaving context switching entirely under the student’s control:

```python
def offer_focus_support(
    user_id,
    activity_data,
    tutor_state,
    consent_state,
    settings
):
    """
    Offers optional in-tutor help. It does not block apps, inspect clipboard
    contents, record URLs, or infer intent from app switching.

    activity_data may include:
      {
        "time_on_problem_sec": int,
        "attempt_count": int,
        "recent_errors": int,
        "hint_dismissals": int,
        "explicit_help_request": bool,
        "external_activity_signal": "none" | "user_reported"
      }
    """

    # Support must be enabled explicitly.
    if not consent_state.get("focus_support_opt_in", False):
        return {"action": "none", "reason": "support_not_enabled"}

    # Do not act on hidden surveillance signals.
    safe_metrics = {
        key: activity_data.get(key)
        for key in (
            "time_on_problem_sec",
            "attempt_count",
            "recent_errors",
            "hint_dismissals",
            "explicit_help_request"
        )
    }

    struggling = (
        safe_metrics["explicit_help_request"] is True
        or safe_metrics["recent_errors"] >= settings["error_threshold"]
        or (
            safe_metrics["time_on_problem_sec"] >= settings["time_threshold"]
            and safe_metrics["attempt_count"] == 0
        )
    )

    if not struggling:
        return {"action": "none", "reason": "no_in_app_need_detected"}

    # Use the least intrusive educational support first.
    if safe_metrics["explicit_help_request"]:
        action = "show_scaffolding_choices"
    elif safe_metrics["hint_dismissals"] >= settings["dismissal_threshold"]:
        action = "offer_alternative_explanation"
    else:
        action = "offer_optional_hint"

    return {
        "action": action,
        "message": (
            "Would you like a hint, a worked example, a simpler explanation, "
            "or to continue independently?"
        ),
        "options": [
            "optional_hint",
            "worked_example",
            "simpler_explanation",
            "continue_independently",
            "use_external_resource",
            "dismiss"
        ],
        "disclosure": (
            "This suggestion is based only on activity in the tutor. "
            "You remain free to use other resources."
        ),
        "controls": {
            "dismissible": True,
            "disable_future_prompts": True,
            "show_reason": True
        }
    }
```

If integration with a browser or operating system is necessary, obtain explicit, granular permission, avoid collecting clipboard text or full URLs, process only minimal local signals, and never block navigation or punish students for leaving. Measure success by learning outcomes and independent problem-solving—not time retained inside the ecosystem.

