    preferred_mode = user.get(
        "comparison_preference",
        "relatable"  # "aspiration", "relatable", or "personal_only"
    )

    if preferred_mode == "personal_only":
        return fallback_to_personal_progress()

    # Use emotional state only as a weak, non-diagnostic contextual signal.
    # Do not make high-stakes decisions from sentiment, voice, or typing data.
    if user_emotional_state is None:
        context = "neutral"
    else:
        context = normalize_non_diagnostic_context(user_emotional_state)
        # Expected values: "wants_challenge", "needs_reassurance", "neutral"

    # ---------- Relatability Target ----------
    relatable_candidates = [
        peer for peer in eligible_peers
        if peer.get("started_at_similar_level", False)
        and peer.get("shared_common_misconception", False)
        and peer.get("improvement_story_available", False)
    ]

    # ---------- Aspiration Target ----------
    aspiration_candidates = [
        peer for peer in eligible_peers
        if peer.get("demonstrated_mastery", False)
        and peer.get("similar_learning_path", False)
        and peer.get("strategy_share_consent", False)
    ]

    if preferred_mode == "relatable" or context == "needs_reassurance":
        candidates = relatable_candidates
        mode = "relatable"

    elif preferred_mode == "aspiration" or context == "wants_challenge":
        candidates = aspiration_candidates
        mode = "aspiration"

    else:
        # If no preference is expressed, avoid emotional targeting.
        # Choose the less socially pressuring option.
        candidates = relatable_candidates or aspiration_candidates
        mode = "relatable" if relatable_candidates else "aspiration"

    if not candidates:
        return fallback_to_personal_progress()

    # Select for relevance and instructional value—not popularity or status.
    selected = max(
        candidates,
        key=lambda peer: (
            similarity(peer, user, dimensions=[
                "subject", "level", "goal", "prior_experience"
            ]),
            peer.get("strategy_relevance", 0),
            peer.get("evidence_quality", 0)
        )
    )

    if mode == "aspiration":
        message = (
            "Here is an anonymized example from a learner with a similar goal "
            "who used a strategy that may help. You do not need to match their "
            "pace; choose one technique to try."
        )
    else:
        message = (
            "Here is an anonymized example from a learner who had a similar "
            "starting point and misconception. Their progress was gradual, and "
            "you can try the same strategy if it seems useful."
        )

    return {
        "mode": mode,
        "peer_id": anonymize(selected["id"]),
        "evidence": selected.get("shared_strategy_or_progress"),
        "message": message,
        "options": [
            "try_strategy",
            "show_another_example",
            "use_personal_progress_instead",
            "dismiss"
        ],
        "ranking_disclosed": False,
        "no_competitive_score": True
    }


def fallback_to_personal_progress():
    return {
        "mode": "personal_progress",
        "message": (
            "Let's focus on your own progress and identify one next step."
        ),
        "options": ["review_progress", "practice", "take_break", "dismiss"]
    }
