```python
def trigger_emotional_intervention(
    user_id: str,
    real_time_metrics: dict,
    historical_data: dict
) -> dict:
    """
    Analyzes real‑time user state and past patterns to select an appropriate
    supportive intervention. Returns a dictionary describing the action.
    """
    # --- Extract real‑time signals ---
    typing_speed = real_time_metrics.get("typing_speed", "normal")   # e.g., "slow", "normal", "fast"
    voice_pitch  = real_time_metrics.get("voice_pitch", "neutral")  # e.g., "low", "neutral", "high"
    sentiment    = real_time_metrics.get("sentiment_score", 0.0)     # -1.0 (negative) to +1.0 (positive)

    # --- Load historical context ---
    progress       = historical_data.get("goal_progress", 0.0)      # 0.0 to 1.0
    fatigue_level  = historical_data.get("fatigue_index", 0.0)     # 0.0 (rested) to 1.0 (exhausted)
    recent_break   = historical_data.get("last_break_minutes_ago", 60)
    micro_goal_size = historical_data.get("current_micro_goal_size", "small") # "small", "medium", "large"

    # --- Decision logic based on emotional state ---

    # 1. Detect frustration / struggle (slow typing, low pitch, negative sentiment)
    if (typing_speed == "slow" and voice_pitch == "low") or sentiment < -0.3:
        # If the student has been working without a break for more than 40 minutes, suggest a pause
        if recent_break > 40 or fatigue_level > 0.7:
            return {
                "type": "break_nudge",
                "message": "You've been working hard. How about a 2‑minute breather? I'll be right here.",
                "next_action": None
            }
        else:
            # Offer a smaller, easier micro‑goal to regain momentum
            return {
                "type": "micro_goal_downsize",
                "message": "Let's try a smaller step. Can you explain just the first part in one sentence?",
                "next_action": {"goal": "explain_first_part", "size": "small"}
            }

    # 2. Detect high motivation / flow (fast typing, high pitch, positive sentiment)
    elif (typing_speed == "fast" and voice_pitch == "high") or sentiment > 0.5:
        # If they are on a roll, offer a slightly larger micro‑goal to challenge them
        if micro_goal_size == "small":
            return {
                "type": "micro_goal_upsize",
                "message": "You're doing great! Want to try a slightly bigger step?",
                "next_action": {"goal": "expand_explanation", "size": "medium"}
            }
        else:
            # Already working at a good pace; reinforce without interruption
            return {
                "type": "positive_reinforcement",
                "message": "Excellent momentum! Keep going—I'll check in before your next milestone.",
                "next_action": None
            }

    # 3. Neutral / bored state (normal metrics)
    else:
        # Use historical data to pre‑emptively suggest the next micro‑commitment
        # (e.g., a 3‑minute recall exercise)
        if progress < 0.8:
            return {
                "type": "proactive_nudge",
                "message": "Ready for a quick review of what you just learned? Only 2 minutes.",
                "next_action": {"goal": "spaced_recall", "size": "tiny"}
            }
        else:
            # Near goal completion: encourage closure
            return {
                "type": "goal_completion_boost",
                "message": "Almost there! Would you like to finish this section now?",
                "next_action": {"goal": "final_exercise", "size": "medium"}
            }
```

**Key design principles behind this pseudocode:**
- **Non‑manipulative:** Interventions are transparent and offer choice (e.g., “Want to try…”).  
- **Adaptive to student state:** The same input (e.g., slow typing) leads to different actions depending on fatigue and break history.  
- **Builds independence:** The tutor encourages micro‑commitments that the student can self‑direct over time.

