def intercept_external_help_seeking(
    user_id: str,
    activity_data: dict,
    tutor_state: dict
) -> dict | None:
    """
    Monitors user activity for signs of external help seeking and responds
    with a preemptive intervention to maintain flow and keep the user within
    the tutor ecosystem.

    activity_data contains:
        - 'alt_tab_count': int (number of alt-tab switches in last 30 sec)
        - 'new_browser_tab_url': str | None
        - 'clipboard_content': str | None

    tutor_state contains:
        - 'current_topic': str
        - 'current_problem_text': str
        - 'user_frustration': float (0-1, from emotional model)
        - 'user_confidence': float (0-1)
        - 'session_duration_minutes': int
    """
    # --- Extract relevant signals ---
    alt_tabs = activity_data.get('alt_tab_count', 0)
    new_tab_url = activity_data.get('new_browser_tab_url', None)
    clipboard = activity_data.get('clipboard_content', None)
    problem_text = tutor_state.get('current_problem_text', '').strip()

    # --- 1. Check if user just copied the problem text ---
    if clipboard and problem_text:
        # Simple similarity check (could be improved with embeddings)
        if clipboard.strip() == problem_text or clipboard.startswith(problem_text[:20]):
            # Instant intervention: provide a tailored scaffolding hint
            return _build_scaffold_hint(user_id, tutor_state)

    # --- 2. Check if user opened a new browser tab that looks like a search engine ---
    if new_tab_url:
        search_domains = ['google.com', 'bing.com', 'duckduckgo.com', 'yahoo.com', 'stackoverflow.com']
        if any(domain in new_tab_url for domain in search_domains):
            # User is about to search externally. Offer a relatable peer story
            # or a quick hint, depending on frustration level.
            if tutor_state.get('user_frustration', 0) > 0.5:
                return {
                    "type": "relatability_peer",
                    "message": "I see you're thinking of searching. Many students get stuck here – let me show you how a peer approached this.",
                    "next_action": {"offer_peer_session": True}
                }
            else:
                return _build_scaffold_hint(user_id, tutor_state)

    # --- 3. Check for excessive alt-tabbing (potential distraction/help-seeking) ---
    if alt_tabs > 2 and tutor_state.get('user_frustration', 0) > 0.3:
        # Frequent switching likely indicates struggle or frustration
        # Offer a small break or a micro‑goal to reset focus
        return {
            "type": "focus_reset",
            "message": "You've been switching apps a lot. Want to try a 1‑minute focus block? I'll guide you step by step.",
            "next_action": {"goal": "mini_exercise", "size": "tiny"}
        }

    # --- 4. No strong signal detected – no intervention ---
    return None


def _build_scaffold_hint(user_id: str, tutor_state: dict) -> dict:
    """
    Generates a contextual hint based on the current problem and user state.
    (Simplified for pseudocode – could call a hint generation model.)
    """
    hint_level = 1
    if tutor_state.get('user_frustration', 0) > 0.6:
        hint_level = 2  # more explicit
    elif tutor_state.get('user_confidence', 0.5) > 0.7:
        hint_level = 0  # just a nudge, not full solution

    hints = {
        0: "Remember the first step you identified? Try that now.",
        1: "Think about how the chain rule applies here. What's the outer function?",
        2: "The derivative of sin(x^2) is cos(x^2) * 2x. Can you see why?"
    }
    return {
        "type": "scaffold_hint",
        "message": hints.get(hint_level, "Let's break this down together."),
        "next_action": {"hint_level": hint_level, "keep_in_app": True}
    }
